-- =============================================================================================
-- Hand-written below this line: announcement text checks; a building only for building
-- audiences; content fixed once published; DRAFT -> PUBLISHED -> WITHDRAWN (reason required),
-- published and withdrawn times and publisher set by the database; recipients only of published
-- announcements, reading and acknowledging only one's own copy, each once (acknowledging also
-- reads); app_property_resident_users() lists the people living at a property (or building)
-- today, by the same rules as app_resident_grants(). See DATA_MODEL section 11 (Communications).
-- =============================================================================================

ALTER TABLE "announcements" ADD CONSTRAINT "announcements_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND "body" = btrim("body") AND length("body") BETWEEN 1 AND 10000
         AND ("withdraw_reason" IS NULL OR ("withdraw_reason" = btrim("withdraw_reason") AND length("withdraw_reason") BETWEEN 1 AND 1000)));
ALTER TABLE "announcements" ADD CONSTRAINT "announcements_building"
  CHECK (("audience" = 'BUILDING_RESIDENTS') = ("building_id" IS NOT NULL));
ALTER TABLE "announcements" ADD CONSTRAINT "announcements_status"
  CHECK (("status" IN ('PUBLISHED', 'WITHDRAWN')) = ("published_at" IS NOT NULL)
         AND ("published_at" IS NULL) = ("published_by_user_id" IS NULL)
         AND ("status" = 'WITHDRAWN') = ("withdrawn_at" IS NOT NULL)
         AND ("status" = 'WITHDRAWN') = ("withdraw_reason" IS NOT NULL));

CREATE FUNCTION app_announcement_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'DRAFT' THEN
      RAISE EXCEPTION 'announcements start as drafts' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."published_at" := NULL;
    NEW."published_by_user_id" := NULL;
    NEW."withdrawn_at" := NULL;
    NEW."withdraw_reason" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" = 'WITHDRAWN' THEN
    RAISE EXCEPTION 'announcement % is withdrawn and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'announcement % stays at its property', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" = 'PUBLISHED'
     AND (NEW."title", NEW."body", NEW."priority", NEW."audience", NEW."building_id", NEW."requires_acknowledgement")
         IS DISTINCT FROM
         (OLD."title", OLD."body", OLD."priority", OLD."audience", OLD."building_id", OLD."requires_acknowledgement") THEN
    RAISE EXCEPTION 'a published announcement never changes; withdraw it and publish another'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."published_at" := OLD."published_at";
  NEW."published_by_user_id" := OLD."published_by_user_id";
  NEW."withdrawn_at" := OLD."withdrawn_at";
  IF NEW."status" = OLD."status" THEN
    NEW."withdraw_reason" := OLD."withdraw_reason";
    RETURN NEW;
  END IF;
  IF (OLD."status" || '>' || NEW."status") NOT IN ('DRAFT>PUBLISHED', 'PUBLISHED>WITHDRAWN') THEN
    RAISE EXCEPTION 'an announcement cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'PUBLISHED' THEN
    IF app_current_user_id() IS NULL THEN
      RAISE EXCEPTION 'an announcement is published by a person' USING ERRCODE = 'check_violation';
    END IF;
    NEW."published_at" := now();
    NEW."published_by_user_id" := app_current_user_id();
    NEW."withdraw_reason" := NULL;
  ELSE
    IF NEW."withdraw_reason" IS NULL THEN
      RAISE EXCEPTION 'say why the announcement is withdrawn' USING ERRCODE = 'check_violation';
    END IF;
    NEW."withdrawn_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "announcements_guard"
  BEFORE INSERT OR UPDATE ON "announcements"
  FOR EACH ROW EXECUTE FUNCTION app_announcement_guard();

CREATE FUNCTION app_announcement_recipient_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM "announcements" WHERE "id" = NEW."announcement_id" AND "status" = 'PUBLISHED') THEN
      RAISE EXCEPTION 'only a published announcement reaches people' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."read_at" := NULL;
    NEW."acknowledged_at" := NULL;
    RETURN NEW;
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."announcement_id", NEW."user_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."announcement_id", OLD."user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'an inbox copy never moves' USING ERRCODE = 'check_violation';
  END IF;
  IF app_current_user_id() IS DISTINCT FROM OLD."user_id" THEN
    RAISE EXCEPTION 'only the recipient reads or acknowledges their copy' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Read and acknowledged once; acknowledging also reads.
  NEW."read_at" := coalesce(OLD."read_at", CASE WHEN NEW."read_at" IS NOT NULL OR NEW."acknowledged_at" IS NOT NULL THEN now() END);
  IF NEW."acknowledged_at" IS NOT NULL AND OLD."acknowledged_at" IS NULL THEN
    IF NOT EXISTS (SELECT 1 FROM "announcements" WHERE "id" = OLD."announcement_id"
                      AND "requires_acknowledgement" AND "status" = 'PUBLISHED') THEN
      RAISE EXCEPTION 'this announcement does not ask for acknowledgement' USING ERRCODE = 'check_violation';
    END IF;
    NEW."acknowledged_at" := now();
  ELSE
    NEW."acknowledged_at" := OLD."acknowledged_at";
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "announcement_recipients_guard"
  BEFORE INSERT OR UPDATE ON "announcement_recipients"
  FOR EACH ROW EXECUTE FUNCTION app_announcement_recipient_guard();

-- People living at a property (or one of its buildings) today with a login: owners, tenants and
-- household members, by the property's local date. Runs under RLS as the caller.
CREATE FUNCTION app_property_resident_users(p_property uuid, p_building uuid)
  RETURNS TABLE ("user_id" uuid)
  LANGUAGE sql STABLE
  AS $$
  WITH today AS (
    SELECT (now() AT TIME ZONE "time_zone")::date AS "d" FROM "properties" WHERE "id" = p_property
  ),
  units AS (
    SELECT "id" FROM "units" WHERE "property_id" = p_property AND "status" = 'ACTIVE'
       AND (p_building IS NULL OR "building_id" = p_building)
  ),
  people AS (
    SELECT o."person_id" FROM "ownerships" o, today
     WHERE o."unit_id" IN (SELECT "id" FROM units) AND o."voided_at" IS NULL
       AND o."effective_from" <= today."d" AND (o."effective_to" IS NULL OR o."effective_to" >= today."d")
    UNION
    SELECT oc."person_id" FROM "tenancy_occupants" oc JOIN "tenancies" tn ON tn."id" = oc."tenancy_id", today
     WHERE tn."unit_id" IN (SELECT "id" FROM units) AND tn."voided_at" IS NULL
       AND tn."start_date" <= today."d" AND (tn."end_date" IS NULL OR tn."end_date" >= today."d")
    UNION
    SELECT h."person_id" FROM "household_members" h, today
     WHERE h."unit_id" IN (SELECT "id" FROM units) AND h."voided_at" IS NULL
       AND h."valid_from" <= today."d" AND (h."valid_to" IS NULL OR h."valid_to" >= today."d")
  )
  SELECT DISTINCT p."user_id" FROM "persons" p
   WHERE p."id" IN (SELECT "person_id" FROM people) AND p."status" = 'ACTIVE' AND p."user_id" IS NOT NULL
$$;

GRANT EXECUTE ON FUNCTION app_property_resident_users(uuid, uuid) TO veyra_app;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['announcements', 'announcement_recipients'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "announcements", "announcement_recipients" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "announcements", "announcement_recipients" TO veyra_app;
